// trendWindows are the last 90 days, the 90 days before and the same 90
// days one year earlier, each as [from, to) of local dates.
type trendWindows struct {
	Cur, Prev, LastYear [2]time.Time
}

const trendDays = 90

func newTrendWindows(today time.Time) trendWindows {
	to := today.AddDate(0, 0, 1)
	from := to.AddDate(0, 0, -trendDays)
	return trendWindows{
		Cur:      [2]time.Time{from, to},
		Prev:     [2]time.Time{from.AddDate(0, 0, -trendDays), from},
		LastYear: [2]time.Time{from.AddDate(-1, 0, 0), to.AddDate(-1, 0, 0)},
	}
}

func (w trendWindows) all() [3][2]time.Time { return [3][2]time.Time{w.Cur, w.Prev, w.LastYear} }

// trendCard lists the notable changes and the stable metrics.
type trendCard struct {
	Statements []insight.Statement
	Stable     string
}

func newTrendCard(metrics []insight.TrendMetric) *trendCard {
	var ts []insight.Trend
	c := &trendCard{}
	for _, m := range metrics {
		if t, ok := insight.AssessTrend(m); ok {
			ts = append(ts, t)
			if !t.Stable {
				c.Statements = append(c.Statements, t.Statement)
			}
		}
	}
	if len(ts) == 0 {
		return nil
	}
	c.Stable = insight.StableLabels(ts)
	return c
}

// minTrendValues is the number of daily values a window needs for a median.
var minTrendValues = map[string]int{insight.RestingHR: 20, insight.HRV: 20, "vo2max_cycling": 1, "vo2max_running": 1}

// healthTrends compares resting HR, HRV and VO2max (medians per window).
func (s *server) healthTrends(ctx context.Context, today time.Time) (*trendCard, error) {
	w := newTrendWindows(today)
	cols := []string{insight.RestingHR, insight.HRV, "vo2max_cycling", "vo2max_running"}
	days, err := s.Store.HealthDays(ctx, w.LastYear[0], today, cols)
	if err != nil {
		return nil, err
	}
	medians := map[string][3]float64{}
	for _, col := range cols {
		var m [3]float64
		for i, win := range w.all() {
			var xs []float64
			for _, d := range days {
				if v, ok := num(d.Values[col]); ok && !d.Date.Before(win[0]) && d.Date.Before(win[1]) {
					xs = append(xs, v)
				}
			}
			m[i] = math.NaN()
			if len(xs) >= minTrendValues[col] {
				m[i] = medianOf(xs)
			}
		}
		medians[col] = m
	}
	metric := func(col, label string, threshold float64, relative, lower bool, unit string, format func(float64) string) insight.TrendMetric {
		m := medians[col]
		return insight.TrendMetric{Label: label, Current: m[0], Previous: m[1], LastYear: m[2], Threshold: threshold,
			Relative: relative, LowerBetter: lower, Unit: unit, Format: format}
	}
	return newTrendCard([]insight.TrendMetric{
		metric(insight.RestingHR, "Ruhepuls", 2, false, true, "bpm", bpm),
		metric(insight.HRV, "HRV", 0.05, true, false, "", ms),
		metric("vo2max_cycling", "VO2max Rad", 1, false, false, "", whole),
		metric("vo2max_running", "VO2max Laufen", 1, false, false, "", whole),
	}), nil
}

func whole(v float64) string { return fmt.Sprintf("%.0f", v) }

func medianOf(xs []float64) float64 {
	s := append([]float64(nil), xs...)
	sort.Float64s(s)
	n := len(s)
	if n%2 == 1 {
		return s[n/2]
	}
	return (s[n/2-1] + s[n/2]) / 2
}

// trainingTrends compares FTP, best efforts of the category and fitness.
func (s *server) trainingTrends(ctx context.Context, catID string, today time.Time) (*trendCard, error) {
	w := newTrendWindows(today)
	var metrics []insight.TrendMetric
	best := func(group, kind string, key int, label string) error {
		var v [3]float64
		for i, win := range w.all() {
			v[i] = math.NaN()
			top, err := s.Store.TopEfforts(ctx, group, kind, key, win[0], win[1], 1)
			if err != nil {
				return err
			}
			if len(top) > 0 {
				v[i] = top[0].Value
			}
		}
		m := insight.TrendMetric{Label: label, Current: v[0], Previous: v[1], LastYear: v[2], Threshold: 0.03, Relative: true}
		if kind == store.EffortDistance {
			m.Time, m.LowerBetter, m.Format = true, true, duration
		} else {
			m.Format = func(x float64) string { return fmt.Sprintf("%.0f W", x) }
		}
		metrics = append(metrics, m)
		return nil
	}
	if catID == "bike" || catID == "indoor" {
		var v [3]float64
		for i, win := range w.all() {
			v[i] = math.NaN()
			ftp, ok, err := s.Store.FTPIn(ctx, win[0], win[1])
			if err != nil {
				return nil, err
			}
			if ok {
				v[i] = float64(ftp)
			}
		}
		metrics = append(metrics, insight.TrendMetric{Label: "FTP", Current: v[0], Previous: v[1], LastYear: v[2],
			Threshold: 0.03, Relative: true, Format: func(x float64) string { return fmt.Sprintf("%.0f W", x) }})
		for _, d := range []int{300, 1200} {
			if err := best(analysis.GroupBike, store.EffortPower, d, "Beste "+analysis.DurationLabel(d)+"-Leistung"); err != nil {
				return nil, err
			}
		}
	}
	switch catID {
	case "bike":
		for _, m := range []int{20000, 40000} {
			if err := best(analysis.GroupBike, store.EffortDistance, m, "Schnellste "+analysis.DistanceLabel(m)); err != nil {
				return nil, err
			}
		}
	case "run":
		for _, m := range []int{5000, 10000} {
			if err := best(analysis.GroupRun, store.EffortDistance, m, "Schnellste "+analysis.DistanceLabel(m)); err != nil {
				return nil, err
			}
		}
	}
	raw, err := s.Store.DailyLoad(ctx, time.Unix(0, 0).UTC(), today.AddDate(0, 0, 1))
	if err != nil {
		return nil, err
	}
	loads := map[time.Time]float64{}
	for _, l := range raw {
		loads[l.Date] = l.Garmin
	}
	fit := map[time.Time]float64{}
	for _, f := range analysis.FitnessSeries(loads, today) {
		fit[f.Date] = f.Fitness
	}
	at := func(d time.Time) float64 {
		if v, ok := fit[d]; ok && v > 0 {
			return v
		}
		return math.NaN()
	}
	// Absolute points: after a break the reference is close to 0 and
	// percentages explode.
	metrics = append(metrics, insight.TrendMetric{Label: "Fitness (alle Sportarten)", Current: at(today),
		Previous: at(today.AddDate(0, 0, -trendDays)), LastYear: at(today.AddDate(-1, 0, 0)),
		Threshold: 5, Unit: "Punkte", Format: whole})
	return newTrendCard(metrics), nil
}

// healthNorms attaches population norms (H) to the health cards.
func (s *server) healthNorms(ctx context.Context, cards []healthCard, latest map[string]store.HealthValue, today time.Time) error {
	p := s.profile(ctx)
	days, err := s.Store.HealthDays(ctx, today.AddDate(0, 0, -30), today.AddDate(0, 0, -1), []string{insight.Sleep, "steps"})
	if err != nil {
		return err
	}
	var sleep, steps []float64
	for _, d := range days {
		if v, ok := num(d.Values[insight.Sleep]); ok && v > 0 {
			sleep = append(sleep, v)
		}
		if v, ok := num(d.Values["steps"]); ok && v > 0 {
			steps = append(steps, v)
		}
	}
	value := func(col string) (float64, bool) {
		v, ok := latest[col]
		if !ok {
			return 0, false
		}
		return num(v.Value)
	}
	for i := range cards {
		c := &cards[i]
		var st insight.Statement
		var ok bool
		switch c.Label {
		case "Ruhepuls":
			if v, has := value(insight.RestingHR); has {
				st, ok = insight.RestingHRNorm(v), true
			}
		case "Schlaf":
			if len(sleep) >= 7 {
				st, ok = insight.SleepNorm(p, avg(sleep)), true
			}
		case "Schritte":
			if len(steps) >= 7 {
				st, ok = insight.StepsNorm(p, avg(steps)), true
			}
		case "VO2max":
			v, has := value("vo2max_cycling")
			if !has {
				v, has = value("vo2max_running")
			}
			if has {
				if st, ok = insight.VO2maxNorm(p, v); !ok {
					st, ok = insight.Statement{Text: "Einordnung nach Alter: Profil unter Mehr → Einordnung angeben", Tone: insight.ToneNeutral}, true
				}
			}
		case "Fitnessalter":
			if v, has := value("fitness_age"); has && p.Known() {
				st, ok = fitnessAgeNorm(v, p.Age), true
			}
		}
		if ok {
			c.Norm = &st
		}
	}
	return nil
}

func fitnessAgeNorm(fitnessAge float64, age int) insight.Statement {
	d := fitnessAge - float64(age)
	switch {
	case d <= -1:
		return insight.Statement{Text: fmt.Sprintf("%s Jahre unter deinem Alter (%d)", germanFloat(-d, 1), age), Tone: insight.ToneGood}
	case d >= 1:
		return insight.Statement{Text: fmt.Sprintf("%s Jahre über deinem Alter (%d)", germanFloat(d, 1), age), Tone: insight.ToneBad}
	}
	return insight.Statement{Text: fmt.Sprintf("etwa dein Alter (%d)", age), Tone: insight.ToneNeutral}
}
